escenas.Mundo:
// MUNDO: «El zumbido que no podían borrar era el Big Bang». Teatro en miniatura de noche, sobre un tablado redondo.
// 3D: antena de bocina de Holmdel (al centro, con un foco cálido), escalera, panel, tarjetas, teléfono, Princeton,
//     reloj, termómetro, televisor y medalla. 2D: personas (Persona2D), palomas, trapo, manchas, onda y luces.
// paso 0: antena con la boca a la derecha, onda de ruido gris delante de la boca, Wilson (gris) con un trapo.
// paso 1: solo la antena con su foco y la onda (las figuras entran durante la escena).
// paso 2: + colinas de Nueva Jersey, escalera, Penzias (rojo) y Wilson junto a la antena.
// paso 3: antena girada hacia el frente; la onda flota sobre Penzias.
// paso 4: + panel de cables conectado a la cabina de la antena.
// paso 5: + nido con dos palomas en el borde de la boca (la antena ya está limpia).
// paso 6: + tres tarjetas colgadas (ciudad, Sol, galaxia) tachadas con X roja; el foco baja.
// paso 7: + colega gris con el teléfono en la mano, mesa y maqueta de Princeton con la ventana encendida.
// paso 8: el teléfono pasa a la mesa, Penzias con el auricular, rayo dorado de Princeton a la antena.
// paso 9: + luz dorada saliendo de la boca, esfera brillante y reloj que gira hacia atrás.
// paso 10: + cúpula de cielo con luz pareja y termómetro helado (2,7 K).
// paso 11: + televisor de tubo con estática bañado de luz dorada.
// paso 12: + medalla de oro colgada entre Penzias y Wilson.
import React from 'react';
import * as THREE from 'three';
import {Pieza, Linea, Cartel, ConoDeLuz, Brillo, Mat} from '../lib3d';
import type {Paleta, V3} from '../lib3d';
import {Persona2D, Sombra} from '../lib25d';

export const PARTES = [
  'antena', 'onda', 'trapo', 'colinas', 'penzias', 'wilson', 'escalera', 'panel', 'nido', 'palomas', 'manchas',
  'tarjetas', 'equis', 'colega', 'mesa', 'telefono', 'auricular', 'princeton', 'rayo', 'luzdorada', 'esfera',
  'reloj', 'cupula', 'termometro', 'televisor', 'medalla',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};
export type PoseP = 'parado' | 'camina' | 'senala' | 'piensa' | 'sorprendida';

const S = 0.05; // alto del tablado
const FPS = 30;
const ALTO_P = 0.6;
const BLANCO = '#ECE8DF';
const METAL = '#7D828C';
const MADERA = '#6B4A32';
const PI = Math.PI;
const col = (p: ParteProps, normal: string) => (p.resaltado ? p.paleta.acentos[2] : normal);

// ---------- Posiciones y estados por paso ----------
export const GIRO_INICIAL = -0.55;
export const GIRO_FINAL = -0.8;
export const giroAntena = (paso: number) => (paso >= 3 ? GIRO_FINAL : GIRO_INICIAL);
const CENTRO: V3 = [0, S, -0.1];
/** Pasa un punto del marco de la antena (eje de la bocina en +x) al mundo. */
export const aMundo = ([x, y, z]: V3, g = GIRO_FINAL): V3 => [
  CENTRO[0] + x * Math.cos(g) + z * Math.sin(g),
  CENTRO[1] + y,
  CENTRO[2] - x * Math.sin(g) + z * Math.cos(g),
];
export const bocaAntena = (paso: number) => aMundo([0.65, 0.8, 0], giroAntena(paso));
export const POS_PENZIAS: V3 = [-0.75, S, 0.45];
export const posWilson = (paso: number): V3 => (paso === 0 ? [0.88, S, 0.62] : [-0.2, S, 0.72]);
export const POS_COLEGA: V3 = [0.88, S, 0.62];
export const posOnda = (paso: number): V3 => (paso >= 3 ? [-0.75, S + 0.92, 0.45] : aMundo([0.84, 0.86, 0], giroAntena(paso)));
export const luzEscena = (paso: number) => (paso < 6 ? 1 : [0.5, 0.55, 0.65, 0.75, 0.75, 0.9, 0.9][Math.min(paso - 6, 6)]);
export const ventanaPrinceton = (paso: number) => (paso >= 8 ? 1 : paso >= 7 ? 0.6 : 0);
const TEL: V3 = [-1.0, S + 0.325, 0.15];
export const AURICULAR_EN_TEL: V3 = [TEL[0], TEL[1] + 0.155, TEL[2]];
export const MANO_PENZIAS: V3 = [-0.69, S + 0.52, 0.48];
export const MANO_COLEGA: V3 = [0.72, S + 0.3, 0.7];
const PR: V3 = [-0.5, S, -0.8];
export const VENTANA: V3 = [PR[0], PR[1] + 0.25, PR[2] + 0.068];
const TARJ: V3[] = [[-0.68, 1.72, -0.6], [0, 1.74, -0.66], [0.68, 1.72, -0.6]];
export const ESFERA: V3 = [0.45, 1.2, -0.72];
export const RELOJ: V3 = [-0.3, 1.25, -0.72];
const TE: V3 = [0.95, S, -0.35];
const TV: V3 = [0.86, S, 0.58];
export const MEDALLA: V3 = [-0.48, S + 0.62, 0.6];
const NIDO = aMundo([0.69, 0.46, 0.12]);

// ---------- Recortes 2D (curvas planas de frente a la cámara) ----------
const forma = (pts: number[][]) => {
  const s = new THREE.Shape();
  s.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i += 2) s.quadraticCurveTo(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  return new THREE.ShapeGeometry(s, 10);
};
const G_PALOMA = forma([[-0.55, 0.1], [-0.1, -0.28], [0.32, 0.05], [0.42, 0.12], [0.42, 0.24], [0.5, 0.27], [0.56, 0.3],
  [0.48, 0.44], [0.34, 0.4], [0.25, 0.3], [0.2, 0.26], [-0.2, 0.3], [-0.55, 0.1]]);
const G_TRAPO = forma([[-0.5, 0], [-0.45, 0.35], [-0.1, 0.3], [0.2, 0.45], [0.45, 0.2], [0.6, -0.05], [0.35, -0.25],
  [0, -0.4], [-0.25, -0.25], [-0.55, -0.25], [-0.5, 0]]);
const G_MANCHA = forma([[-0.4, 0], [-0.4, 0.3], [-0.1, 0.25], [0.1, 0.45], [0.3, 0.2], [0.5, 0.05], [0.3, -0.15],
  [0.1, -0.35], [-0.15, -0.2], [-0.45, -0.25], [-0.4, 0]]);

const Silueta: React.FC<{g: THREE.ShapeGeometry; color: string; posicion: V3; escala: number; espejo?: boolean; giro?: number}> = ({
  g, color, posicion, escala, espejo = false, giro = 0,
}) => (
  <group position={posicion} rotation={[0, 0, giro]} scale={[espejo ? -escala : escala, escala, escala]}>
    <mesh geometry={g} position={[0, 0, -0.02]} scale={1.14}>
      <meshBasicMaterial color="#1B1B1F" />
    </mesh>
    <mesh geometry={g}>
      <Mat color={color} />
    </mesh>
  </group>
);

const azar = (n: number) => {
  const s = Math.sin(n * 12.9898) * 43758.5453;
  return s - Math.floor(s);
};

// ---------- Tablado y fondo ----------
const Tablado: React.FC = () => (
  <group>
    <Pieza forma="cilindro" medidas={[1.2, 1.24, S, 64]} color="#24232B" posicion={[0, S / 2, 0]} />
    <Pieza forma="toro" medidas={[1.21, 0.01]} color="#7A6440" rotacion={[PI / 2, 0, 0]} posicion={[0, S, 0]} contorno={false} />
  </group>
);

export const Colinas: React.FC<ParteProps> = (p) => {
  const verde = col(p, '#2F523C');
  const cerros: number[][] = [[-0.72, 0.42, 0.9, -0.92], [0.08, 0.55, 1.05, -1.0], [0.82, 0.4, 0.85, -0.9]];
  const arboles: number[][] = [[-0.85, 0.27, -0.86], [-0.58, 0.3, -0.86], [0.28, 0.45, -0.92], [0.95, 0.27, -0.84]];
  return (
    <group>
      {cerros.map(([x, r, h, z], i) => (
        <Pieza key={i} forma="media_esfera" medidas={[r]} color={i === 1 ? '#2A4A37' : verde} posicion={[x, S, z]} escala={[1, h, 0.42]} />
      ))}
      <Pieza forma="caja" medidas={[2.1, 0.05, 0.06]} color="#4A3424" posicion={[0, S + 0.025, -0.74]} />
      {arboles.map(([x, y, z], i) => (
        <Pieza key={i} forma="cono" medidas={[0.045, 0.15]} color="#1F3A2B" posicion={[x, S + y + 0.07, z]} />
      ))}
    </group>
  );
};

// ---------- La antena de bocina (protagonista) ----------
export const Antena: React.FC<ParteProps & {giro?: number}> = (p) => {
  const {giro = GIRO_FINAL} = p;
  const blanco = col(p, BLANCO);
  const ruedas: number[][] = [[0.5, 0.2], [0.5, -0.2], [-0.5, 0.2], [-0.5, -0.2]];
  return (
    <group>
      <Sombra posicion={[CENTRO[0], S + 0.003, CENTRO[2]]} radio={0.8} />
      <group position={CENTRO} rotation={[0, giro, 0]}>
        {/* riel circular, pedestal y ruedas */}
        <Pieza forma="toro" medidas={[0.56, 0.014]} color={METAL} rotacion={[PI / 2, 0, 0]} posicion={[0, 0.014, 0]} />
        <Pieza forma="cilindro" medidas={[0.13, 0.17, 0.12]} color="#5E626C" posicion={[0, 0.06, 0]} />
        {ruedas.map(([x, z], i) => (
          <Pieza key={i} forma="cilindro" medidas={[0.05, 0.05, 0.04]} color="#3A3D45" rotacion={[PI / 2, 0, 0]} posicion={[x, 0.06, z]} />
        ))}
        {/* plataforma y soportes */}
        <Pieza forma="caja" medidas={[1.22, 0.07, 0.5]} color={METAL} posicion={[0, 0.15, 0]} />
        <Pieza forma="caja" medidas={[0.06, 0.27, 0.06]} color={METAL} posicion={[0.5, 0.32, 0]} />
        <Pieza forma="caja" medidas={[0.06, 0.5, 0.06]} color={METAL} posicion={[-0.58, 0.43, 0]} />
        {[-1, 1].map((l) => (
          <Pieza key={l} forma="caja" medidas={[0.07, 0.34, 0.06]} color={METAL} posicion={[-0.05, 0.35, 0.3 * l]} />
        ))}
        <Pieza forma="toro" medidas={[0.42, 0.028]} color="#A9ADB6" posicion={[-0.05, 0.8, 0]} rotacion={[0, PI / 2, 0]} />
        {/* bocina cuadrada que se abre hacia +x */}
        <group position={[0.025, 0.8, 0]} rotation={[0, 0, -PI / 2]}>
          <Pieza forma="cilindro" medidas={[0.52, 0.06, 1.25, 4]} color={blanco} rotacion={[0, PI / 4, 0]} />
          {[-0.2, 0.25].map((y) => {
            const r = 0.06 + (0.46 * (y + 0.625)) / 1.25 + 0.012;
            return <Pieza key={y} forma="cilindro" medidas={[r, r, 0.035, 4]} color="#C9C6BE" posicion={[0, y, 0]} rotacion={[0, PI / 4, 0]} />;
          })}
        </group>
        {/* boca: interior oscuro con profundidad */}
        <Pieza forma="caja" medidas={[0.012, 0.7, 0.7]} color="#0B0C10" posicion={[0.652, 0.8, 0]} contorno={false} />
        <Pieza forma="caja" medidas={[0.004, 0.4, 0.4]} color="#16171D" posicion={[0.659, 0.8, 0]} contorno={false} />
        <Pieza forma="caja" medidas={[0.004, 0.16, 0.16]} color="#22242C" posicion={[0.662, 0.8, 0]} contorno={false} />
        {/* cabina del receptor */}
        <Pieza forma="caja" medidas={[0.24, 0.26, 0.24]} color="#9A9EA8" posicion={[-0.7, 0.8, 0]} />
        <Pieza forma="caja" medidas={[0.1, 0.16, 0.01]} color="#2B2E36" posicion={[-0.7, 0.78, 0.121]} />
      </group>
    </group>
  );
};

/** Onda de ruido: siempre el mismo trazo; solo vibra un poco. */
const TRAZO = Array.from({length: 25}, (_, i) => azar(i + 3) - 0.5);
export const Onda: React.FC<ParteProps & {posicion?: V3}> = (p) => {
  const {frame = 0, posicion = posOnda(0)} = p;
  const c = col(p, p.paleta.acentos[1]);
  const pts: V3[] = TRAZO.map((r, i) => [-0.34 + (i * 0.68) / 24, r * 0.17 * Math.sin((PI * i) / 24) * (0.85 + 0.15 * Math.sin(frame * 0.9 + i)), 0]);
  return (
    <group position={[posicion[0], posicion[1] + Math.sin(frame / 22) * 0.015, posicion[2]]}>
      {pts.slice(1).map((pt, i) => (
        <Linea key={i} desde={pts[i]} hasta={pt} grosor={0.011} color={c} brillo />
      ))}
      <pointLight color={c} intensity={0.25} distance={0.8} />
    </group>
  );
};

export const Trapo: React.FC<ParteProps> = (p) => <Silueta g={G_TRAPO} color={col(p, '#C8D2DC')} posicion={[0.66, S + 0.42, 0.68]} escala={0.12} giro={0.3} />;

// ---------- Personas ----------
type PersonaProps = ParteProps & {pose?: PoseP; posicion?: V3; espejo?: boolean};
const Figura: React.FC<{color: string; pose?: PoseP; posicion: V3; espejo?: boolean; frame?: number}> = ({color, pose = 'parado', posicion, espejo = false, frame = 0}) => (
  <group>
    <Persona2D pose={pose} color={color} alto={ALTO_P} posicion={posicion} espejo={espejo} frame={frame} fps={FPS} />
    <Sombra posicion={[posicion[0], S + 0.003, posicion[2]]} radio={0.16} />
  </group>
);
export const Penzias: React.FC<PersonaProps> = (p) => (
  <Figura color={col(p, p.paleta.acentos[0])} pose={p.pose} posicion={p.posicion ?? POS_PENZIAS} espejo={p.espejo} frame={p.frame} />
);
export const Wilson: React.FC<PersonaProps> = (p) => (
  <Figura color={col(p, p.paleta.acentos[1])} pose={p.pose} posicion={p.posicion ?? posWilson(2)} espejo={p.espejo} frame={p.frame} />
);
export const Colega: React.FC<PersonaProps> = (p) => (
  <Figura color={col(p, '#6F727B')} pose={p.pose} posicion={p.posicion ?? POS_COLEGA} espejo={p.espejo ?? true} frame={p.frame} />
);

export const Escalera: React.FC<ParteProps> = (p) => {
  const c = col(p, '#B08A55');
  return (
    <group position={[-0.28, S, 0.22]} rotation={[0, GIRO_FINAL, 0]}>
      <Sombra posicion={[0, 0.003, 0]} radio={0.12} />
      <group rotation={[-0.35, 0, 0]}>
        {[-1, 1].map((l) => (
          <Pieza key={l} forma="caja" medidas={[0.022, 0.36, 0.022]} color={c} posicion={[0.07 * l, 0.18, 0]} />
        ))}
        {[0.08, 0.18, 0.28].map((y) => (
          <Pieza key={y} forma="caja" medidas={[0.14, 0.014, 0.016]} color={c} posicion={[0, y, 0]} />
        ))}
      </group>
    </group>
  );
};

// ---------- Panel de cables ----------
export const Panel: React.FC<ParteProps & {luz?: number}> = (p) => {
  const {luz = 1} = p;
  const cab = aMundo([-0.7, 0.68, 0]);
  const luces = ['#5BD16A', p.paleta.acentos[2], '#E5533D'];
  const cables = ['#1B1B1F', '#C0392B', '#D9B44A'];
  return (
    <group>
      <group position={[-0.92, S, -0.38]} rotation={[0, 0.5, 0]}>
        <Sombra posicion={[0, 0.003, 0]} radio={0.24} />
        <Pieza forma="caja" medidas={[0.32, 0.56, 0.16]} color={col(p, '#3C4A5E')} posicion={[0, 0.28, 0]} />
        <Pieza forma="caja" medidas={[0.24, 0.22, 0.012]} color="#1F2530" posicion={[0, 0.38, 0.085]} />
        {Array.from({length: 12}, (_, i) => (
          <mesh key={i} position={[-0.075 + (i % 4) * 0.05, 0.31 + Math.floor(i / 4) * 0.065, 0.093]}>
            <circleGeometry args={[0.011, 10]} />
            <meshBasicMaterial color="#C9CDD6" />
          </mesh>
        ))}
        <Linea desde={[-0.075, 0.31, 0.1]} hasta={[0.025, 0.375, 0.11]} grosor={0.006} color="#D9B44A" />
        <Linea desde={[-0.025, 0.44, 0.1]} hasta={[0.075, 0.31, 0.11]} grosor={0.006} color="#C0392B" />
        {luces.map((c, i) => {
          const on = i !== 1 || luz > 0.5;
          return <Pieza key={i} forma="esfera" medidas={[0.018]} color={on ? c : '#2A2A30'} brillo={on ? c : undefined} posicion={[-0.08 + 0.08 * i, 0.18, 0.085]} />;
        })}
      </group>
      {cables.map((c, i) => {
        const a: V3 = [-0.8, S + 0.5 - i * 0.03, -0.36];
        const m: V3 = [-0.66, S + 0.4 - i * 0.03, -0.5];
        return (
          <group key={i}>
            <Linea desde={a} hasta={m} grosor={0.008} color={c} />
            <Linea desde={m} hasta={[cab[0], cab[1] - i * 0.02, cab[2]]} grosor={0.008} color={c} />
          </group>
        );
      })}
    </group>
  );
};

// ---------- Nido, palomas y manchas (en el borde de la boca) ----------
export const Nido: React.FC<ParteProps> = (p) => (
  <group position={NIDO}>
    <Pieza forma="toro" medidas={[0.07, 0.028]} color={col(p, '#7A5C3A')} rotacion={[PI / 2, 0, 0]} />
    <Pieza forma="cilindro" medidas={[0.07, 0.05, 0.03]} color="#5A4229" posicion={[0, -0.01, 0]} />
  </group>
);
const PAL: [number, number, boolean][] = [[-0.06, 0, false], [0.07, 0.01, true]];
export const Palomas: React.FC<ParteProps> = (p) => (
  <group>
    {PAL.map(([dx, dy, e], i) => (
      <Silueta key={i} g={G_PALOMA} color={col(p, '#9A9DA6')} posicion={[NIDO[0] + dx, NIDO[1] + 0.05 + dy, NIDO[2] + 0.06]}
        escala={0.13} espejo={e} giro={Math.sin(((p.frame ?? 0) + i * 40) / 25) * 0.08} />
    ))}
  </group>
);
export const Manchas: React.FC<ParteProps> = (p) => (
  <group>
    {[-0.18, 0.02, 0.2].map((z, i) => (
      <Silueta key={i} g={G_MANCHA} color={col(p, '#F4F1EA')} posicion={aMundo([0.67, 0.5 + 0.03 * i, z])} escala={0.06} giro={i} />
    ))}
  </group>
);

// ---------- Tarjetas: ciudad, Sol, galaxia, y sus X rojas ----------
export const Tarjetas: React.FC<ParteProps> = (p) => (
  <group>
    {TARJ.map((t, i) => (
      <group key={i} position={t} rotation={[0, -t[0] * 0.35, 0]}>
        {[-1, 1].map((l) => (
          <Linea key={l} desde={[0.14 * l, 0.18, 0]} hasta={[0.14 * l, 1.98 - t[1], 0]} grosor={0.004} color="#5A5A60" />
        ))}
        <Pieza forma="caja" medidas={[0.36, 0.36, 0.02]} color={col(p, '#E9E2D2')} />
        <group position={[0, 0, 0.012]}>
          {i === 0
            ? [[-0.09, 0.07, 0.16], [-0.01, 0.07, 0.24], [0.08, 0.07, 0.13]].map(([x, w, h], k) => (
                <Pieza key={k} forma="caja" medidas={[w, h, 0.01]} color="#3E4A66" posicion={[x, -0.15 + h / 2, 0]} />
              ))
            : null}
          {i === 1 ? (
            <>
              <Pieza forma="esfera" medidas={[0.085]} color="#F2A33A" brillo="#B9610F" escala={[1, 1, 0.25]} />
              <Pieza forma="toro" medidas={[0.13, 0.008]} color="#E08A1E" contorno={false} />
            </>
          ) : null}
          {i === 2 ? (
            <>
              <Pieza forma="esfera" medidas={[0.03]} color="#F4E7C2" brillo="#8A7440" escala={[1, 1, 0.3]} />
              {Array.from({length: 28}, (_, k) => {
                const n = k % 14;
                const a = n * 0.45 + (k >= 14 ? PI : 0);
                const r = 0.03 + n * 0.0105;
                return (
                  <mesh key={k} position={[r * Math.cos(a), r * Math.sin(a) * 0.75, 0.01]}>
                    <circleGeometry args={[0.011 - n * 0.0004, 8]} />
                    <meshBasicMaterial color="#8FA6E8" toneMapped={false} />
                  </mesh>
                );
              })}
            </>
          ) : null}
        </group>
      </group>
    ))}
  </group>
);
export const Equis: React.FC<ParteProps> = (p) => (
  <group>
    {TARJ.map((t, i) => (
      <group key={i} position={t} rotation={[0, -t[0] * 0.35, 0]}>
        {[1, -1].map((l) => (
          <Pieza key={l} forma="caja" medidas={[0.44, 0.045, 0.015]} color={col(p, p.paleta.acentos[0])} rotacion={[0, 0, (l * PI) / 4]} posicion={[0, 0, 0.03]} />
        ))}
      </group>
    ))}
  </group>
);

// ---------- Mesa, teléfono de disco y auricular ----------
export const Mesa: React.FC<ParteProps> = (p) => (
  <group position={[TEL[0], S, TEL[2]]}>
    <Sombra posicion={[0, 0.003, 0]} radio={0.2} />
    <Pieza forma="caja" medidas={[0.34, 0.03, 0.28]} color={col(p, MADERA)} posicion={[0, 0.31, 0]} />
    <Pieza forma="cilindro" medidas={[0.025, 0.03, 0.3]} color="#4A3322" posicion={[0, 0.15, 0]} />
    <Pieza forma="cilindro" medidas={[0.1, 0.12, 0.02]} color="#4A3322" posicion={[0, 0.01, 0]} />
  </group>
);
export const Telefono: React.FC<ParteProps> = (p) => {
  const c = col(p, '#2E3140');
