export const Rayo: React.FC<ParteProps> = (p) => {
  const {frame = 0} = p;
  const a = VENTANA;
  const b = bocaAntena(8);
  const m: V3 = [(a[0] + b[0]) / 2, 1.45, (a[2] + b[2]) / 2];
  const q = (t: number) => [0, 1, 2].map((k) => (1 - t) * (1 - t) * a[k] + 2 * (1 - t) * t * m[k] + t * t * b[k]) as V3;
  const c = col(p, '#FFE2A0');
  const pts = Array.from({length: 17}, (_, i) => q(i / 16));
  return (
    <group>
      {pts.slice(1).map((pt, i) => (
        <Linea key={i} desde={pts[i]} hasta={pt} grosor={0.011} color={c} brillo />
      ))}
      <Brillo posicion={q((frame % 40) / 40)} color={p.paleta.acentos[2]} radio={0.035} />
      <Brillo posicion={b} color={c} radio={0.04} luz={0.8} />
    </group>
  );
};

