// ---------- El mundo según el paso ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, paleta, ocultar = [], resaltar = []}) => {
  const P = (n: string) => ({paleta, frame, resaltado: resaltar.includes(n)});
  const v = (n: string, desde = 0, hasta = 99) => paso >= desde && paso <= hasta && !ocultar.includes(n);
  const luz = luzEscena(paso);
  const enMano: V3 = [MANO_COLEGA[0] - TEL[0], MANO_COLEGA[1] - TEL[1], MANO_COLEGA[2] - TEL[2]];
  const posePenzias: PoseP = paso === 4 || paso === 5 ? 'piensa' : 'parado';
  return (
    <group>
      <Tablado />
      {/* foco cálido sobre la antena */}
      <ConoDeLuz posicion={[0.1, S, 0]} altura={2.1} radio={0.95} color="#FFD49A" opacidad={0.055 * luz} />
      <pointLight position={[0.3, 1.95, 0.9]} color="#FFC37A" intensity={2.2 * luz} distance={4.5} decay={2} />

      {v('colinas', 2) ? <Colinas {...P('colinas')} /> : null}
      {v('antena') ? <Antena {...P('antena')} giro={giroAntena(paso)} /> : null}
      {v('onda') ? <Onda {...P('onda')} posicion={posOnda(paso)} /> : null}
      {v('trapo', 0, 0) ? <Trapo {...P('trapo')} /> : null}
      {v('wilson') && paso !== 1 ? <Wilson {...P('wilson')} posicion={posWilson(paso)} espejo={paso === 0} pose={paso === 0 ? 'senala' : 'parado'} /> : null}
      {v('penzias', 2) ? <Penzias {...P('penzias')} pose={posePenzias} /> : null}
      {v('escalera', 2) ? <Escalera {...P('escalera')} /> : null}
      {v('panel', 4) ? <Panel {...P('panel')} /> : null}
      {v('nido', 5) ? <Nido {...P('nido')} /> : null}
      {v('palomas', 5) ? <Palomas {...P('palomas')} /> : null}
      {v('tarjetas', 6) ? <Tarjetas {...P('tarjetas')} /> : null}
      {v('equis', 6) ? <Equis {...P('equis')} /> : null}

      {v('colega', 7, 7) ? <Colega {...P('colega')} pose="senala" /> : null}
      {v('mesa', 7) ? <Mesa {...P('mesa')} /> : null}
      {paso === 7 ? (
        <group position={enMano}>
          {v('telefono') ? <Telefono {...P('telefono')} /> : null}
          {v('auricular') ? <Auricular {...P('auricular')} posicion={AURICULAR_EN_TEL} rotacion={[0, 0.35, 0]} /> : null}
        </group>
      ) : null}
      {v('telefono', 8) ? <Telefono {...P('telefono')} /> : null}
      {v('auricular', 8) ? (
        <group>
          <Auricular {...P('auricular')} />
          <Linea desde={[TEL[0] + 0.1, TEL[1] + 0.03, TEL[2] + 0.05]} hasta={[-0.82, S + 0.25, 0.42]} grosor={0.005} color="#2E3140" />
          <Linea desde={[-0.82, S + 0.25, 0.42]} hasta={[MANO_PENZIAS[0], MANO_PENZIAS[1] - 0.09, MANO_PENZIAS[2]]} grosor={0.005} color="#2E3140" />
        </group>
      ) : null}
      {v('princeton', 7) ? <Princeton {...P('princeton')} ventana={ventanaPrinceton(paso)} /> : null}
      {v('rayo', 8) ? <Rayo {...P('rayo')} /> : null}

      {v('luzdorada', 9) ? <LuzDorada {...P('luzdorada')} /> : null}
      {v('esfera', 9) ? <Esfera {...P('esfera')} /> : null}
      {v('reloj', 9) ? <Reloj {...P('reloj')} /> : null}
      {v('cupula', 10) ? <Cupula {...P('cupula')} /> : null}
      {v('termometro', 10) ? <Termometro {...P('termometro')} /> : null}
      {v('televisor', 11) ? <Televisor {...P('televisor')} /> : null}
      {v('medalla', 12) ? <Medalla {...P('medalla')} /> : null}
    </group>
  );
};

escenas.Escena3:
// Escena 4: «Revisan cables. Apagan equipos. Nada cambia.»
// 3D: el panel de cables cae junto a la antena; su luz se apaga y se vuelve a encender.
// 2D: Penzias (rojo) y Wilson (gris) revisan; la onda de ruido sigue igual encima de ellos.
import React from 'react';
import {EscenaProps, Etiqueta, Flecha, Brillo, Linea, aparecer, momento, caer} from '../lib3d';
import type {V3} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Panel, Penzias, Wilson, POS_PENZIAS, posWilson, posOnda, aMundo} from './Mundo';

const PASO = 3;
const S = 0.05;

// Luz del medio del panel (la que se apaga), en coordenadas del mundo.
const LUZ_PANEL: V3 = [-0.92 + 0.085 * Math.sin(0.5), S + 0.18, -0.38 + 0.085 * Math.cos(0.5)];

// Camino de los cables: del panel a la cabina del receptor.
const CAB = aMundo([-0.7, 0.68, 0]);
const A: V3 = [-0.8, S + 0.5, -0.36];
const M: V3 = [-0.66, S + 0.4, -0.5];
const B: V3 = [CAB[0], CAB[1], CAB[2]];
const enCable = (t: number): V3 => {
  const lerp = (p: V3, q: V3, u: number): V3 => [p[0] + (q[0] - p[0]) * u, p[1] + (q[1] - p[1]) * u, p[2] + (q[2] - p[2]) * u];
  return t < 0.35 ? lerp(A, M, t / 0.35) : lerp(M, B, (t - 0.35) / 0.65);
};

export const Escena3: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte] = paleta.acentos;

  const tRevisan = momento(palabras, fps, 'Revisan', 1);
  const tCables = momento(palabras, fps, 'cables', 15);
  const tApagan = momento(palabras, fps, 'Apagan', 47);
  const tEquipos = momento(palabras, fps, 'equipos', 56);
  const tNada = momento(palabras, fps, 'Nada', 90);
  const tCambia = momento(palabras, fps, 'cambia', 100);

  // 1) El panel cae en su sitio junto a la antena.
  const c = caer(frame, fps, tRevisan + 7, 1.0, true);

  // 2) "cables": el panel se resalta y aparece su etiqueta.
  const resaltaPanel = frame >= tCables && frame < tCables + 36;
  const etiCables = aparecer(frame, tCables, 8) * (1 - aparecer(frame, tApagan - 6, 6));

  // 3) "Apagan equipos": la luz del panel se apaga y vuelve a encender.
  const apagado = frame >= tApagan + 2 && frame < tEquipos + 20;
  const vuelve = tEquipos + 20;
  const flecha = aparecer(frame, tEquipos - 4, 8) * (1 - aparecer(frame, tNada - 6, 6));

  // 4) "Nada cambia": la onda se resalta igual que siempre.
  const resaltaOnda = frame >= tNada && frame < tNada + 38;
  const etiNada = aparecer(frame, tNada, 8) * (1 - aparecer(frame, Math.min(duracion - 10, tCambia + 30), 8));

  // Poses: revisan el panel y, al final, Penzias se queda pensando (como en el paso 4).
  const posePenzias = frame < tNada ? 'senala' : 'piensa';
  const wilsonSenala = frame >= tApagan && frame < tNada - 2;

  // Partículas de señal corriendo por los cables (se paran al apagar).
  const corriente = frame > tRevisan + 8 && !apagado;
  const particulas = [0, 0.33, 0.66].map((d) => ((frame / 28 + d) % 1));

  const onda = posOnda(PASO);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['penzias', 'wilson']} resaltar={resaltaOnda ? ['onda'] : []} />

      {/* Panel de cables (lo nuevo de esta escena) */}
      <group position={[0, c.y, 0]}>
        <Panel paleta={paleta} resaltado={resaltaPanel} luz={apagado ? 0 : 1} />
      </group>

      {/* Señal que corre por los cables */}
      {corriente
        ? particulas.map((t, i) => <Brillo key={i} posicion={enCable(t)} color={resalte} radio={0.018} />)
        : null}

      {/* Brillo de la luz del panel cuando vuelve */}
      {frame >= vuelve && frame < vuelve + 14 ? (
        <Efecto tipo="destello" posicion={[LUZ_PANEL[0], LUZ_PANEL[1], LUZ_PANEL[2] + 0.05]} tam={0.28} frame={frame - vuelve} fps={fps} />
      ) : null}
      {!apagado && frame > tRevisan + 8 ? <Brillo posicion={[LUZ_PANEL[0], LUZ_PANEL[1], LUZ_PANEL[2] + 0.01]} color={resalte} radio={0.012} luz={0.4} /> : null}

      {/* Flecha que señala la luz que se apaga */}
      <Flecha desde={[-0.45, 0.62, 0.05]} hasta={[LUZ_PANEL[0] + 0.06, LUZ_PANEL[1] + 0.06, LUZ_PANEL[2] + 0.04]} color={resalte} grosor={0.018} progreso={flecha} />

      {/* Personas */}
      <Penzias paleta={paleta} frame={frame} pose={posePenzias} espejo={posePenzias === 'senala'} posicion={POS_PENZIAS} />
      <Wilson paleta={paleta} frame={frame} pose={wilsonSenala ? 'senala' : 'parado'} espejo={wilsonSenala} posicion={posWilson(PASO)} />

      {/* Línea punteada de la onda: sigue en el mismo sitio */}
      {resaltaOnda ? (
        <Linea desde={[onda[0] - 0.36, onda[1] - 0.12, onda[2]]} hasta={[onda[0] + 0.36, onda[1] - 0.12, onda[2]]} grosor={0.005}
          color={resalte} discontinua progreso={aparecer(frame, tNada, 12)} brillo />
      ) : null}

      {/* Textos (máximo uno a la vez) */}
      <Etiqueta texto="cables" punto={[-0.72, S + 0.42, -0.45]} desplazamiento={[-0.23, 0.88, 0.25]} escala={etiCables} />
      <Etiqueta texto="nada cambia" punto={[onda[0] + 0.15, onda[1] + 0.1, onda[2]]} desplazamiento={[0.1, 0.42, 0.05]} escala={etiNada} />
    </group>
  );
};

escenas.Escena1:
// Escena 2 · «Nueva Jersey, 1964. Arno Penzias y Robert Wilson, de Bell Labs, ajustan una antena gigante de seis metros.»
// 3D: antena (se ajusta con un leve giro), colinas que se levantan, escalera que cae. 2D: Penzias y Wilson entran caminando.
import React from 'react';
import {EscenaProps, Etiqueta, Medida, ConoDeLuz, aparecer, momento, mover, caer} from '../lib3d';
import type {V3} from '../lib3d';
import {Mundo, Antena, Onda, Colinas, Escalera, Penzias, Wilson, aMundo, GIRO_INICIAL, POS_PENZIAS, posWilson} from './Mundo';

const S = 0.05;

export const Escena1: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const tNueva = momento(palabras, fps, 'Nueva', 1);
  const tJersey = momento(palabras, fps, 'Jersey', Math.round(1.73 * fps));
  const tAno = momento(palabras, fps, '1964', Math.round(1.95 * fps));
  const tPenzias = momento(palabras, fps, 'Penzias', Math.round(4.25 * fps));
  const tWilson = momento(palabras, fps, 'Wilson', Math.round(5.13 * fps));
  const tBell = momento(palabras, fps, 'Bell', Math.round(5.99 * fps));
  const tAjustan = momento(palabras, fps, 'ajustan', Math.round(6.85 * fps));
  const tAntena = momento(palabras, fps, 'antena', Math.round(7.41 * fps));
  const tSeis = momento(palabras, fps, 'seis', Math.round(8.33 * fps));
  const enRango = (a: number, b: number) => frame >= a && frame < b;

  // 1) Las colinas de Nueva Jersey se levantan desde el tablado (primer golpe).
  const sube = aparecer(frame, tNueva, 18);
  const colinasY = Math.max(0.001, sube * (1 + 0.12 * Math.sin(sube * Math.PI)));

  // 2) Foco: destello en «1964» y se desliza hacia donde entra Penzias.
  const destello = aparecer(frame, tAno, 5) * (1 - aparecer(frame, tAno + 6, 20));
  const focoX = mover(frame, [tAno + 30, tPenzias + 10], [0.1, POS_PENZIAS[0]]);
  const focoVis = aparecer(frame, tAno + 30, 12) * (1 - aparecer(frame, tWilson + 20, 30));
  const etiqueta1964 = aparecer(frame, tAno, 10) * (1 - aparecer(frame, tPenzias - 12, 10));

  // 3) Penzias entra caminando desde la izquierda (0,66 u/s).
  const pIni = tPenzias - 10;
  const pFin = tPenzias + 24;
  const pX = mover(frame, [pIni, pFin], [-1.5, POS_PENZIAS[0]]);
  const pCamina = frame >= pIni && frame < pFin;
  const pPose = pCamina ? 'camina' : enRango(tAjustan, tAntena + 10) ? 'senala' : 'parado';

  // 4) Wilson entra caminando desde la derecha (0,71 u/s) y se gira al llegar.
  const wFinal = posWilson(2);
  const wIni = tWilson - 6;
  const wFin = tWilson + 34;
  const wX = mover(frame, [wIni, wFin], [0.75, wFinal[0]]);
  const wCamina = frame >= wIni && frame < wFin;

  // 5) La escalera cae en «Bell».
  const esc = caer(frame, fps, tBell + 4, 1.4);

  // 6) «ajustan»: la antena gira un poco y vuelve a su sitio.
  const ajuste = aparecer(frame, tAjustan, 30);
  const giro = GIRO_INICIAL + 0.14 * Math.sin(ajuste * Math.PI * 2) * (1 - ajuste * 0.3);
  const ondaPos = aMundo([0.84, 0.86, 0], giro);

  // 7) «seis metros»: cota de altura junto a la antena.
  const cota = aparecer(frame, tSeis, 14) * (1 - aparecer(frame, duracion - 8, 7));

  const antenaRes = enRango(tAntena, tAntena + 36);
  const colinasRes = enRango(tJersey, tJersey + 36);
  const penziasRes = enRango(tPenzias, tPenzias + 36);
  const wilsonRes = enRango(tWilson, tWilson + 36);
  const escRes = enRango(tBell + 4, tBell + 36);

  const ladder: V3 = [-0.28, 0, 0.22];

  return (
    <group>
      <Mundo paso={1} frame={frame} fps={fps} paleta={paleta} ocultar={['colinas', 'antena', 'onda']} />

      {/* destello del año sobre el escenario */}
      {destello > 0.01 ? <pointLight position={[0, 1.6, 1.2]} color="#FFE2A8" intensity={3 * destello} distance={4} /> : null}

      {/* colinas que se levantan */}
      <group scale={[1, colinasY, 1]}>
        <Colinas paleta={paleta} resaltado={colinasRes} />
      </group>

      {/* antena y su onda de ruido */}
      <Antena paleta={paleta} giro={giro} resaltado={antenaRes} />
      <Onda paleta={paleta} frame={frame} posicion={ondaPos} />

      {/* foco que sigue a quien entra */}
      {focoVis > 0.01 ? (
        <group>
          <ConoDeLuz posicion={[focoX, S, 0.45]} altura={1.6} radio={0.35} color="#FFD49A" opacidad={0.07 * focoVis} />
          <pointLight position={[focoX, 1.1, 0.8]} color="#FFC37A" intensity={1.2 * focoVis} distance={2} />
        </group>
      ) : null}

      {/* escalera */}
      {esc.escala > 0.001 ? (
        <group position={[ladder[0], esc.y, ladder[2]]} rotation={[0, 0, esc.giro]} scale={esc.escala}>
          <group position={[-ladder[0], 0, -ladder[2]]}>
            <Escalera paleta={paleta} resaltado={escRes} />
          </group>
        </group>
      ) : null}

      {/* personas */}
      {frame >= pIni ? (
        <Penzias paleta={paleta} frame={frame} pose={pPose} posicion={[pX, S, POS_PENZIAS[2]]} resaltado={penziasRes} />
      ) : null}
      {frame >= wIni ? (
        <Wilson paleta={paleta} frame={frame} pose={wCamina ? 'camina' : 'parado'} espejo={wCamina}
          posicion={[wX, S, wFinal[2]]} resaltado={wilsonRes} />
      ) : null}

      {/* textos */}
      <Etiqueta texto="1964" punto={[-0.72, S + 0.36, -0.92]} desplazamiento={[-0.1, 0.95, 0.5]} escala={etiqueta1964}
        color={paleta.acentos[2]} alto={0.2} />
      <Medida desde={[1.0, S, 0.3]} hasta={[1.0, 1.35, 0.3]} texto="6 m" progreso={cota} />
    </group>
  );
};

escenas.Escena0:
// Escena 1 (gancho): «No limpies esa antena: lo que oyes no es basura.»
// 3D: la antena de bocina (Mundo). 2D: Wilson, el trapo que sale volando, destellos y ondas.
// Empieza como <Mundo paso={0} /> y termina como <Mundo paso={1} />: Wilson y el trapo se van.
import React from 'react';
import {EscenaProps, Etiqueta, Brillo, aparecer, momento, mover} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Onda, Trapo, Wilson, posOnda, posWilson, bocaAntena} from './Mundo';
import type {V3} from '../lib3d';

const PASO = 0;
const S = 0.05;
const BASE_TRAPO: V3 = [0.66, S + 0.42, 0.68];

export const Escena0: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte] = paleta.acentos;
  const tLimpies = momento(palabras, fps, 'limpies', 19);
  const tAntena = momento(palabras, fps, 'antena', 38);
  const tOyes = momento(palabras, fps, 'oyes', 76);
  const tNo = momento(palabras, fps, 'no', 94);
  const tBasura = momento(palabras, fps, 'basura', 112);
  const tNoFinal = tNo > tOyes ? tNo : Math.max(tOyes + 16, 94);

  // --- Onda de ruido: se calienta (dorada) en cuanto empieza a sonar, y empuja el trapo ---
  const ondaDorada = frame >= 4 && frame < tAntena;
  const empuje = aparecer(frame, tLimpies - 3, 6) * (1 - aparecer(frame, tLimpies + 4, 10));
  const pulsoOyes = aparecer(frame, tOyes, 6) * (1 - aparecer(frame, tOyes + 8, 14));
  const escalaOnda = 1 + 0.35 * empuje + 0.4 * pulsoOyes + 0.08 * aparecer(frame, 0, 8) * (1 - aparecer(frame, tLimpies, 6));
  const pOnda = posOnda(PASO);

  // --- Trapo: frota la boca, y en «limpies» sale volando hacia la cámara ---
  const frota = frame < tLimpies ? Math.sin(frame * 0.9) * 0.025 : 0;
  const acerca = aparecer(frame, 0, tLimpies);
  const vuela = aparecer(frame, tLimpies, 22);
  const vuelaE = vuela * vuela;
  const trapoPos: V3 = [
    BASE_TRAPO[0] - 0.07 * acerca + frota + 1.1 * vuelaE,
    BASE_TRAPO[1] + 0.05 * acerca + 1.0 * vuela - 0.2 * vuelaE,
    BASE_TRAPO[2] + 1.5 * vuelaE,
  ];
  const trapoGiro = vuela * 5.5;
  const trapoEscala = 1 + 2.2 * vuelaE;
  const verTrapo = vuela < 1;

  // --- Wilson: frota, se sobresalta y se va caminando a la derecha ---
  const pW = posWilson(PASO);
  const tSale = tLimpies + 20;
  const tFuera = tSale + 54; // 1,8 s caminando
  const caminando = frame >= tSale && frame < tFuera;
  const wx = mover(frame, [tSale, tFuera], [pW[0], pW[0] + 0.8 * ((tFuera - tSale) / fps)]);
  const poseW = frame < tLimpies ? 'senala' : frame < tSale ? 'sorprendida' : caminando ? 'camina' : 'parado';
  const salto = frame >= tLimpies && frame < tSale ? Math.sin(((frame - tLimpies) / (tSale - tLimpies)) * Math.PI) * 0.05 : 0;
  const verWilson = frame < tFuera;

  // --- Resaltes del mundo ---
  const resaltar: string[] = [];
  if (frame >= tAntena && frame < tAntena + 36) resaltar.push('antena');

  // --- Destello del golpe y ondas al «oyes» ---
  const destello = frame >= tLimpies - 2 && frame < tLimpies + 14;
  const luzGolpe = Math.max(0, 1 - Math.abs(frame - tLimpies) / 10);
  const boca = bocaAntena(PASO);
  const verOndas = frame >= tOyes && frame < tOyes + 30;
  const destelloBasura = frame >= tBasura && frame < tBasura + 10;

  // --- Etiquetas (máximo una a la vez, a la derecha de la boca) ---
  const punto: V3 = [pOnda[0] + 0.15, pOnda[1] + 0.05, pOnda[2]];
  const desp: V3 = [0.22, 0.5, 0.2];
  const e1 = aparecer(frame, tLimpies, 8) * (1 - aparecer(frame, tOyes - 8, 6));
  const e2 = aparecer(frame, tNoFinal, 8) * (1 - aparecer(frame, duracion - 6, 5));

  // Polvo en el foco (capa delante y medio), fijo y suave
  const polvo = Array.from({length: 10}, (_, i) => {
    const a = i * 2.4;
    const r = 0.35 + (i % 4) * 0.17;
    const y = 0.4 + ((i * 0.37 + frame * 0.004) % 1) * 1.3;
    return [r * Math.cos(a + frame * 0.01), y, 0.1 + r * Math.sin(a + frame * 0.01)] as V3;
  });

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['onda', 'trapo', 'wilson']} resaltar={resaltar} />

      {/* onda de ruido (gris → dorada → gris), late con la voz */}
      <group position={pOnda} scale={escalaOnda}>
        <Onda paleta={paleta} frame={frame} resaltado={ondaDorada} posicion={[0, 0, 0]} />
      </group>

      {/* Wilson con su trapo */}
      {verWilson ? (
        <Wilson paleta={paleta} frame={frame} pose={poseW} posicion={[wx, pW[1] + salto, pW[2]]} espejo={frame < tSale} />
      ) : null}
      {verTrapo ? (
        <group position={trapoPos} rotation={[trapoGiro * 0.4, trapoGiro * 0.3, trapoGiro]} scale={trapoEscala}>
          <group position={[-BASE_TRAPO[0], -BASE_TRAPO[1], -BASE_TRAPO[2]]}>
            <Trapo paleta={paleta} frame={frame} />
          </group>
        </group>
      ) : null}

      {/* golpe: destello dorado en la onda */}
      {destello ? <Efecto tipo="destello" posicion={[pOnda[0], pOnda[1], pOnda[2] + 0.1]} tam={0.7} color={resalte} frame={frame} fps={fps} /> : null}
      {luzGolpe > 0 ? <pointLight position={[pOnda[0], pOnda[1], pOnda[2] + 0.3]} color={resalte} intensity={3 * luzGolpe} distance={2.5} /> : null}

      {/* el sonido sale de la boca de la antena */}
      {verOndas ? <Efecto tipo="ondas" posicion={[boca[0] + 0.1, boca[1], boca[2] + 0.12]} tam={0.6} color={paleta.acentos[1]} frame={frame} fps={fps} /> : null}
      {destelloBasura ? <Efecto tipo="chispa" posicion={[pOnda[0], pOnda[1] + 0.05, pOnda[2] + 0.1]} tam={0.4} color={resalte} frame={frame} fps={fps} /> : null}

      {/* polvo en el foco */}
      {polvo.map((p, i) => (
        <Brillo key={i} posicion={p} color="#FFE2B0" radio={0.006 + (i % 3) * 0.003} />
      ))}

      <Etiqueta texto="no limpies" punto={punto} desplazamiento={desp} escala={e1} color={resalte} />
      <Etiqueta texto="no es basura" punto={punto} desplazamiento={desp} escala={e2} />
    </group>
  );
};

escenas.Escena2:
// Escena 3 · «Quieren escuchar el cielo. Pero hay un siseo constante, de día y de noche, en todas direcciones.»
// 3D: la antena gira despacio hacia distintos puntos del cielo (sol, luna, todo alrededor).
// 2D/luz: la onda de ruido vuela sobre Penzias y cada nueva dirección trae una copia con el MISMO trazo.
import React from 'react';
import {EscenaProps, Flecha, Etiqueta, Linea, Pieza, Brillo, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Mundo, Antena, Onda, Penzias, aMundo, posOnda, GIRO_INICIAL, GIRO_FINAL} from './Mundo';
import type {PoseP} from './Mundo';

const PI = Math.PI;
const lerp3 = (a: V3, b: V3, k: number): V3 => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
const boca = (g: number) => aMundo([0.84, 0.86, 0], g);

const ESTRELLAS: V3[] = [
  [-0.95, 1.62, -0.55], [-0.45, 1.82, -0.8], [0.15, 1.86, -0.95], [0.7, 1.74, -0.7], [1.0, 1.5, -0.2], [-0.8, 1.4, 0.2], [0.55, 1.85, 0.1],
];
const CIELO: V3[] = [
  [-1.0, 1.8, -0.5], [0.0, 1.9, -0.95], [1.0, 1.75, -0.35], [0.95, 1.55, 0.55], [-0.95, 1.6, 0.45],
];
const CENTRO_CIELO: V3 = [0.05, 1.0, -0.1];

export const Escena2: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte, extra] = paleta.acentos;
  const tEscuchar = momento(palabras, fps, 'escuchar', 9);
  const tCielo = momento(palabras, fps, 'cielo', 26);
  const tSiseo = momento(palabras, fps, 'siseo', 74);
  const tConstante = momento(palabras, fps, 'constante', 88);
  const tDia = momento(palabras, fps, 'día', 129);
  const tNoche = momento(palabras, fps, 'noche', 141);
  const tTodas = momento(palabras, fps, 'todas', 175);
  const fin = duracion;

  // Giro de la antena: escucha hacia un lado, luego hacia el día, la noche y vuelve al frente.
  const tLuna = tNoche + 16;
  const giroEn = (f: number) =>
    mover(f, [0, tEscuchar, tSiseo, tDia + 4, tLuna, tTodas, tTodas + 30], [GIRO_INICIAL, GIRO_INICIAL, 0.1, 0.1, -1.5, -1.5, GIRO_FINAL]);
  const giro = giroEn(frame);

  // Onda principal: en la boca hasta «siseo», luego vuela sobre la cabeza de Penzias.
  const vuela = aparecer(frame, tSiseo, 22);
  const cabeza = posOnda(3);
  const base = lerp3(boca(giro), cabeza, vuela);
  const posOndaAhora: V3 = [base[0], base[1] + 0.3 * Math.sin(PI * vuela), base[2]];
  const ondaResaltada = frame >= tSiseo && frame < tSiseo + 40;

  // Ecos: cada nueva dirección trae el mismo trazo, que se funde con el de Penzias.
  const eco = (t: number, clave: string) => {
    const a = aparecer(frame, t, 6);
    const b = aparecer(frame, t + 10, 20);
    if (a <= 0.001 || b >= 0.999) return null;
    const p = lerp3(boca(giroEn(t)), cabeza, b);
    return (
      <group key={clave} position={[p[0], p[1] + 0.2 * Math.sin(PI * b), p[2]]} scale={a * (1 - 0.5 * b)}>
        <Onda paleta={paleta} frame={frame} posicion={[0, 0, 0]} resaltado />
      </group>
    );
  };

  // Haz de escucha: línea discontinua que sale de la boca hacia donde apunta.
  const haz = aparecer(frame, tEscuchar, 14) * (1 - aparecer(frame, fin - 22, 14));
  const hazDesde = aMundo([0.68, 0.82, 0], giro);
  const hazHasta = aMundo([1.12, 1.08, 0], giro);

  // Cielo: estrellas al decir «cielo»; sol de «día», luna de «noche».
  const estrellas = aparecer(frame, tCielo, 10) * (1 - aparecer(frame, fin - 25, 18));
  const sol = aparecer(frame, tDia, 8) * (1 - aparecer(frame, tNoche + 4, 10));
  const luna = aparecer(frame, tNoche + 2, 8) * (1 - aparecer(frame, tTodas + 12, 12));

  // Flechas desde todo el cielo.
  const todas = aparecer(frame, tTodas, 12) * (1 - aparecer(frame, fin - 20, 14));

  // Rótulo junto a la onda sobre Penzias.
  const rotulo = aparecer(frame, tConstante, 10) * (1 - aparecer(frame, fin - 16, 10));

  // Poses: se sorprende con el siseo, piensa con el día y la noche, vuelve a quedarse parado.
  const pose: PoseP = frame >= tSiseo && frame < tSiseo + 40 ? 'sorprendida' : frame >= tDia && frame < tTodas + 20 ? 'piensa' : 'parado';

  return (
    <group>
      <Mundo paso={2} frame={frame} fps={fps} paleta={paleta} ocultar={['antena', 'onda', 'penzias']} />
      <Antena paleta={paleta} frame={frame} giro={giro} />
      <Penzias paleta={paleta} frame={frame} pose={pose} />
      <Onda paleta={paleta} frame={frame} posicion={posOndaAhora} resaltado={ondaResaltada} />
      {eco(tDia, 'dia')}
      {eco(tLuna, 'noche')}

      {/* haz de escucha */}
      {haz > 0.001 ? <Linea desde={hazDesde} hasta={hazHasta} grosor={0.009} color="#F2EFE9" discontinua progreso={haz} /> : null}

      {/* estrellas del cielo */}
      {estrellas > 0.001
        ? ESTRELLAS.map((e, i) => (
            <Brillo key={i} posicion={e} color="#F2EFE9" radio={(0.012 + 0.006 * Math.sin(frame / 6 + i * 1.7)) * estrellas} />
          ))
        : null}

      {/* sol del día */}
      {sol > 0.001 ? (
        <group position={[0.95, 1.55, -0.35]} scale={sol}>
          <Pieza forma="esfera" medidas={[0.09]} color={extra} brillo={extra} intensidadBrillo={0.6} escala={[1, 1, 0.4]} />
          {Array.from({length: 8}, (_, k) => (
            <Pieza key={k} forma="caja" medidas={[0.018, 0.06, 0.012]} color={resalte}
              posicion={[0.14 * Math.sin((k * PI) / 4), 0.14 * Math.cos((k * PI) / 4), 0]} rotacion={[0, 0, (-k * PI) / 4]} />
          ))}
          <pointLight color={resalte} intensity={0.6} distance={2} />
        </group>
      ) : null}

      {/* luna de la noche */}
      {luna > 0.001 ? (
        <group position={[0.35, 1.6, 0.55]} scale={luna}>
          <Pieza forma="esfera" medidas={[0.085]} color="#E9E4D6" escala={[1, 1, 0.4]} />
          <Pieza forma="esfera" medidas={[0.075]} color="#121318" posicion={[0.045, 0.03, 0.03]} escala={[1, 1, 0.4]} contorno={false} />
          <pointLight color="#9FB4F0" intensity={0.4} distance={1.6} />
        </group>
      ) : null}

      {/* el siseo llega desde todas direcciones */}
      {CIELO.map((d, i) => (
        <Flecha key={i} desde={d} hasta={lerp3(d, CENTRO_CIELO, 0.45)} color={paleta.acentos[3]} grosor={0.02}
          progreso={Math.max(0, Math.min(1, todas * 1.4 - i * 0.08))} />
      ))}

      <Etiqueta texto="siempre igual" punto={[cabeza[0], cabeza[1] + 0.14, cabeza[2]]} desplazamiento={[0.3, 0.42, 0.05]} escala={rotulo} color="#F2EFE9" />
    </group>
  );
};

escenas.Escena4:
// Escena 5: «Dentro de la antena habían anidado palomas. Limpian sus excrementos, uno por uno. Y el zumbido sigue ahí.»
// 3D: la antena, el nido (cae). 2D: Wilson con el trapo, las palomas que se asoman, las manchas y las ondas del zumbido.
import React from 'react';
import {EscenaProps, Etiqueta, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Wilson, Trapo, Nido, Palomas, aMundo, posWilson, posOnda, GIRO_FINAL} from './Mundo';

const PASO = 4;
const S = 0.05;
const TRAPO_BASE: V3 = [0.66, S + 0.42, 0.68];
const NIDO: V3 = aMundo([0.69, 0.46, 0.12]);
const Z_MANCHAS = [-0.18, 0.02, 0.2];
const MANCHAS: V3[] = Z_MANCHAS.map((z, i) => aMundo([0.672, 0.5 + 0.03 * i, z]));
const W_INICIO = posWilson(PASO);
const W_LIMPIA: V3 = [0.88, S, 0.62];

/** Mancha blanca 2D pegada a la cara de la boca de la antena (con contorno). */
const Mancha: React.FC<{posicion: V3; escala: number; giro: number}> = ({posicion, escala, giro}) => {
  if (escala <= 0.001) return null;
  const gotas: [number, number, number][] = [[0, 0, 0.028], [0.026, 0.012, 0.018], [-0.02, -0.014, 0.016]];
  return (
    <group position={posicion} rotation={[0, GIRO_FINAL + Math.PI / 2, 0]}>
      <group rotation={[0, 0, giro]} scale={escala}>
        {gotas.map(([x, y, r], k) => (
          <group key={k} position={[x, y, 0]}>
            <mesh position={[0, 0, -0.002]}>
              <circleGeometry args={[r + 0.006, 16]} />
              <meshBasicMaterial color="#1B1B1F" />
            </mesh>
            <mesh>
              <circleGeometry args={[r, 16]} />
              <meshBasicMaterial color="#F4F1EA" />
            </mesh>
          </group>
        ))}
      </group>
    </group>
  );
};

export const Escena4: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const s = (seg: number) => Math.round(seg * fps);
  const tDentro = Math.max(1, momento(palabras, fps, 'dentro', 1));
  const tAntena = momento(palabras, fps, 'antena', s(0.61));
  const tAnidado = momento(palabras, fps, 'anidado', s(1.33));
  const tPalomas = momento(palabras, fps, 'palomas', s(1.79));
  const tLimpian = momento(palabras, fps, 'limpian', s(2.83));
  const tExcr = momento(palabras, fps, 'excrementos', s(3.25));
  const tUno = momento(palabras, fps, 'uno', s(4.39));
  const tPor = momento(palabras, fps, 'por', s(4.79));
  const tUno2 = tPor + s(0.38);
  const tZumbido = momento(palabras, fps, 'zumbido', s(6.17));
  const tSigue = momento(palabras, fps, 'sigue', s(6.55));
  const fin = Math.max(duracion - 1, tSigue + 40);

  // ---- Resaltes de lo que se nombra ----
  const resaltar: string[] = [];
  if (frame >= tAntena && frame < Math.min(tAntena + s(1.1), tPalomas)) resaltar.push('antena');
  if (frame >= tZumbido && frame < tZumbido + s(1.3)) resaltar.push('onda');
  const palomasResalte = frame >= tPalomas && frame < tPalomas + s(1.2);

  // ---- Wilson: camina hasta la boca, limpia y vuelve ----
  const llega = tDentro + 42;
  const vuelveIni = tSigue - 6;
  const vuelveFin = Math.min(vuelveIni + 42, fin - 2);
  const wx = mover(frame, [tDentro, llega, vuelveIni, vuelveFin], [W_INICIO[0], W_LIMPIA[0], W_LIMPIA[0], W_INICIO[0]]);
  const wz = mover(frame, [tDentro, llega, vuelveIni, vuelveFin], [W_INICIO[2], W_LIMPIA[2], W_LIMPIA[2], W_INICIO[2]]);
  const caminaIda = frame >= tDentro && frame < llega;
  const caminaVuelta = frame >= vuelveIni && frame < vuelveFin;
  const limpiando = frame >= tLimpian && frame < tUno2 + 14;
  const poseW = caminaIda || caminaVuelta ? 'camina' : limpiando ? 'senala' : 'parado';
  const espejoW = caminaVuelta || (frame >= llega && frame < vuelveIni);

  // ---- Nido (cae) y palomas (se asoman) ----
  const nido = aparecer(frame, tAnidado - 6, 12);
  const nidoY = (1 - nido) * (1 - nido) * 0.9 + (frame > tAnidado + 6 ? Math.exp(-(frame - tAnidado - 6) / 5) * Math.sin((frame - tAnidado - 6) / 1.6) * 0.03 : 0);
  const asoma = aparecer(frame, tPalomas - 3, 9);
  const palomaY = -0.09 * (1 - asoma) + Math.max(0, Math.sin(Math.min(1, asoma) * Math.PI)) * 0.03;
  const etiqueta = aparecer(frame, tPalomas, 8) * (1 - aparecer(frame, tPalomas + s(1.4), 8));

  // ---- Manchas: salen una a una y se limpian uno por uno ----
  const tLimpia = [tUno, tPor, tUno2];
  const manchas = MANCHAS.map((_, i) => {
    const sale = aparecer(frame, tExcr + i * 5, 6);
    const pulso = frame >= tExcr + i * 5 && frame < tExcr + i * 5 + 8 ? 1 + 0.25 * Math.sin(((frame - tExcr - i * 5) / 8) * Math.PI) : 1;
    return sale * pulso * (1 - aparecer(frame, tLimpia[i] + 5, 5));
  });

  // ---- Trapo: aparece en la mano, frota cada mancha y se va con Wilson ----
  const trapoVis = aparecer(frame, tLimpian, 6) * (1 - aparecer(frame, vuelveIni - 8, 6));
  const ks = [tUno - 7, tUno, tPor, tUno2, tUno2 + 12];
  const objetivo = (k: number): V3 => {
    const m = MANCHAS[k];
    return [m[0] - TRAPO_BASE[0] + 0.03, m[1] - TRAPO_BASE[1], m[2] - TRAPO_BASE[2] + 0.06];
  };
  const pts: V3[] = [[0, 0, 0], objetivo(0), objetivo(1), objetivo(2), [0, 0, 0]];
  const frota = frame >= tUno && frame < tUno2 + 8 ? Math.sin(frame * 1.1) * 0.025 : 0;
  const saluda = frame >= tLimpian && frame < tUno - 7 ? Math.sin((frame - tLimpian) * 0.5) * 0.03 : 0;
  const ofs: V3 = [0, 1, 2].map((c) => mover(frame, ks, pts.map((p) => p[c]))) as V3;
  const trapoPos: V3 = [TRAPO_BASE[0] + ofs[0] + frota, TRAPO_BASE[1] + ofs[1] + saluda, TRAPO_BASE[2] + ofs[2]];

  // ---- El zumbido sigue: ondas alrededor de la onda de ruido ----
  const onda = posOnda(PASO);
  const zumbido = aparecer(frame, tZumbido, 10);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['wilson']} resaltar={resaltar} />

      {/* luz de trabajo sobre la boca mientras limpian */}
      <pointLight position={[0.95, 1.15, 0.95]} color="#FFD49A" intensity={0.7 * aparecer(frame, tDentro, 20)} distance={1.8} decay={2} />

      {/* Wilson con el trapo */}
      <Wilson paleta={paleta} frame={frame} pose={poseW} espejo={espejoW} posicion={[wx, S, wz]} />
      {trapoVis > 0.001 ? (
        <group position={trapoPos} scale={trapoVis}>
          <group position={[-TRAPO_BASE[0], -TRAPO_BASE[1], -TRAPO_BASE[2]]}>
            <Trapo paleta={paleta} />
          </group>
        </group>
      ) : null}

      {/* nido que cae en el borde de la boca y palomas que se asoman */}
      {nido > 0.001 ? (
        <group position={[0, nidoY, 0]}>
          <Nido paleta={paleta} />
        </group>
      ) : null}
      {asoma > 0.001 ? (
        <group position={[0, palomaY, 0]}>
          <Palomas paleta={paleta} frame={frame} resaltado={palomasResalte} />
        </group>
      ) : null}
      <Etiqueta texto="palomas" punto={[NIDO[0], NIDO[1] + 0.1, NIDO[2] + 0.05]} desplazamiento={[0.42, 0.72, 0.1]} escala={etiqueta} />

      {/* excrementos en la boca: salen y se limpian uno por uno */}
      {MANCHAS.map((m, i) => (
        <Mancha key={i} posicion={m} escala={manchas[i]} giro={i * 1.3} />
      ))}
      {tLimpia.map((t, i) =>
        frame >= t + 4 && frame < t + 16 ? (
          <Efecto key={i} tipo="destello" posicion={[MANCHAS[i][0] + 0.04, MANCHAS[i][1], MANCHAS[i][2] + 0.06]} tam={0.22} color="#FFF4D8" frame={frame - t} fps={fps} />
        ) : null,
      )}

      {/* el zumbido sigue ahí: ondas alrededor de la onda de ruido */}
      {zumbido > 0.001 ? (
        <group scale={1}>
          <Efecto tipo="ondas" posicion={[onda[0], onda[1], onda[2] + 0.02]} tam={0.75 * zumbido} fuerza={zumbido} color={paleta.acentos[1]} frame={frame} fps={fps} />
        </group>
      ) : null}
    </group>
  );
};
